-- Slot typed storage. 0013/0014 are reserved for the separately owned poker schema.
CREATE TABLE games.slot_results (
 round_id UUID PRIMARY KEY,
 game_slug TEXT GENERATED ALWAYS AS ('slot'::text) STORED,
 stop_1 SMALLINT NOT NULL CHECK (stop_1 BETWEEN 0 AND 31),
 stop_2 SMALLINT NOT NULL CHECK (stop_2 BETWEEN 0 AND 31),
 stop_3 SMALLINT NOT NULL CHECK (stop_3 BETWEEN 0 AND 31),
 stop_4 SMALLINT NOT NULL CHECK (stop_4 BETWEEN 0 AND 31),
 stop_5 SMALLINT NOT NULL CHECK (stop_5 BETWEEN 0 AND 31),
 -- Reel-major, top/middle/bottom. Typed array, no alternate JSON result authority.
 full_grid TEXT[] NOT NULL CHECK (cardinality(full_grid)=15 AND array_position(full_grid,NULL) IS NULL AND full_grid <@ ARRAY['L1','L2','L3','M1','M2','H1','H2','W']),
 total_wager_units BIGINT NOT NULL CHECK (total_wager_units>=5000000 AND total_wager_units%500000=0),
 line_stake_units BIGINT NOT NULL CHECK (line_stake_units=total_wager_units/10),
 total_payout_units BIGINT NOT NULL CHECK (total_payout_units>=0),
 net_change_units BIGINT NOT NULL CHECK (net_change_units::numeric=total_payout_units::numeric-total_wager_units::numeric),
 result_detail TEXT NOT NULL CHECK (result_detail IN ('NO_WIN','PARTIAL_RETURN','BREAK_EVEN','WIN')),
 reel_strip_version TEXT NOT NULL CHECK (reel_strip_version='slot-strips-v1'),
 payline_version TEXT NOT NULL CHECK (payline_version='slot-paylines-v1'),
 paytable_version TEXT NOT NULL CHECK (paytable_version='slot-paytable-v1'),
 FOREIGN KEY(round_id,game_slug) REFERENCES games.game_rounds(round_id,game_slug)
);
CREATE TABLE games.slot_line_results (
 round_id UUID NOT NULL REFERENCES games.slot_results,
 line_number SMALLINT NOT NULL CHECK (line_number BETWEEN 1 AND 10),
 interpreted_symbol TEXT NOT NULL CHECK (interpreted_symbol IN ('','L1','L2','L3','M1','M2','H1','H2','W')),
 match_length SMALLINT NOT NULL CHECK (match_length IN (0,3,4,5)),
 multiplier BIGINT NOT NULL CHECK (multiplier BETWEEN 0 AND 5000),
 line_stake_units BIGINT NOT NULL CHECK (line_stake_units>0),
 line_payout_units BIGINT NOT NULL CHECK (line_payout_units::numeric=line_stake_units::numeric*multiplier::numeric),
 PRIMARY KEY(round_id,line_number),
 CHECK ((multiplier=0 AND interpreted_symbol='' AND match_length=0) OR (multiplier>0 AND interpreted_symbol<>'' AND match_length>=3))
);
CREATE TRIGGER immutable_history BEFORE UPDATE OR DELETE OR TRUNCATE ON games.slot_results FOR EACH STATEMENT EXECUTE FUNCTION economy.reject_history_change();
CREATE TRIGGER immutable_history BEFORE UPDATE OR DELETE OR TRUNCATE ON games.slot_line_results FOR EACH STATEMENT EXECUTE FUNCTION economy.reject_history_change();
CREATE FUNCTION games.check_slot_result() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE s games.slot_results; n bigint; paid numeric; BEGIN
 IF NEW.game_slug<>'slot' THEN RETURN NULL; END IF;
 SELECT * INTO STRICT s FROM games.slot_results WHERE round_id=NEW.round_id;
 SELECT count(*),sum(line_payout_units) INTO n,paid FROM games.slot_line_results WHERE round_id=NEW.round_id AND line_stake_units=s.line_stake_units;
 IF n<>10 OR paid<>NEW.total_payout_units OR s.total_wager_units<>NEW.total_stake_units OR s.total_payout_units<>NEW.total_payout_units OR s.net_change_units<>NEW.net_change_units THEN RAISE EXCEPTION 'slot typed settlement mismatch'; END IF;
 RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER slot_result_complete AFTER INSERT ON games.game_rounds DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION games.check_slot_result();

